import { Instruction as JupiterInstruction, QuoteResponse, SwapInstructionsResponse } from '@jup-ag/api';
import BN from 'bn.js';
import { QuoteParams, RouteParams, unwrapSolIx } from '../swap_api_utils';
import { RouterType } from '../consts';
import { determineRole, getAllLookupTables, removeComputeBudgetIxns } from '../utils';
import { WRAPPED_SOL_MINT } from '@kamino-finance/limo-sdk';
import { AccountRole, address, Instruction, Rpc, SolanaRpcApi } from '@solana/kit';

export abstract class JupiterBase {
  protected constructor(
    readonly routerType: RouterType,
    readonly connection: Rpc<SolanaRpcApi>,
  ) {}

  async getRouteOutput(
    instructions: SwapInstructionsResponse,
    quoteResponse: QuoteResponse,
    params: RouteParams,
    timeAfterGetQuote: number,
    timeBeforeGetQuote: number,
  ) {
    const { setupInstructions, swapInstruction, addressLookupTableAddresses } = instructions;
    const lookupTablePubkeys = addressLookupTableAddresses.map((addr) => address(addr));
    const lookupTableAccounts = await getAllLookupTables(this.connection, lookupTablePubkeys);

    const timeAfterSwapIxsRequest = Date.now();

    const ixsSetupJupiter = setupInstructions.map((ix) => this.convertJupiterToTransactionInstruction(ix));
    const ixsJupiter = [
      ...(params.includeSetupIxs ? ixsSetupJupiter : []),
      this.convertJupiterToTransactionInstruction(swapInstruction),
    ];

    const filteredIxsJupiter = removeComputeBudgetIxns(ixsJupiter);

    const priceImpactBps = Number(quoteResponse.priceImpactPct) * 100;

    if (params.wrapAndUnwrapSol) {
      if (params.tokenIn === WRAPPED_SOL_MINT) {
        filteredIxsJupiter.push(await unwrapSolIx(params, undefined));
      } else if (params.tokenOut === WRAPPED_SOL_MINT) {
        filteredIxsJupiter.push(await unwrapSolIx(params, params.destinationTokenAccount));
      }
    }

    return {
      ixsRouter: filteredIxsJupiter,
      amountsExactIn: {
        amountIn: params.swapType === 'exactIn' ? params.amount : new BN(0),
        amountOutGuaranteed: params.swapType === 'exactIn' ? new BN(quoteResponse.otherAmountThreshold) : new BN(0),
        amountOut: params.swapType === 'exactIn' ? new BN(quoteResponse.outAmount) : new BN(0),
      },
      amountsExactOut: {
        amountOut: params.swapType === 'exactOut' ? params.amount : new BN(0),
        amountInGuaranteed:
          params.swapType === 'exactOut' ? new BN(quoteResponse.otherAmountThreshold.toString()) : new BN(0),
        amountIn: params.swapType === 'exactOut' ? new BN(quoteResponse.inAmount.toString()) : new BN(0),
      },
      swapType: params.swapType,
      responseTimeGetQuoteMs: timeAfterGetQuote - timeBeforeGetQuote,
      responseTimeSwapIxsMs: timeAfterSwapIxsRequest - timeAfterGetQuote,
      lookupTableAccounts: lookupTableAccounts,
      routerType: this.routerType,
      expiryTime: 0,
      priceImpactBps,
    };
  }

  async getQuoteOutput(
    quoteResponse: QuoteResponse,
    params: QuoteParams,
    timeAfterGetQuoteData: number,
    timeBeforeGetQuoteData: number,
  ) {
    const priceImpactBps = Number(quoteResponse.priceImpactPct) * 100;

    return {
      amountsExactIn: {
        amountIn: params.swapType === 'exactIn' ? params.amount : new BN(0),
        amountOutGuaranteed: params.swapType === 'exactIn' ? new BN(quoteResponse.otherAmountThreshold) : new BN(0),
        amountOut: params.swapType === 'exactIn' ? new BN(quoteResponse.outAmount) : new BN(0),
      },
      amountsExactOut: {
        amountOut: params.swapType === 'exactOut' ? params.amount : new BN(0),
        amountInGuaranteed:
          params.swapType === 'exactOut' ? new BN(quoteResponse.otherAmountThreshold.toString()) : new BN(0),
        amountIn: params.swapType === 'exactOut' ? new BN(quoteResponse.outAmount.toString()) : new BN(0),
      },
      swapType: params.swapType,
      responseTimeGetQuoteMs: timeAfterGetQuoteData - timeBeforeGetQuoteData,
      responseTimeSwapIxsMs: 0,
      routerType: this.routerType,
      expiryTime: 0,
      priceImpactBps,
    };
  }

  private convertJupiterToTransactionInstruction(instruction: JupiterInstruction): Instruction {
    return {
      programAddress: address(instruction.programId),
      accounts: instruction.accounts.map((key) => ({
        address: address(key.pubkey),
        role: determineRole(key.isSigner, key.isWritable),
      })),
      data: Buffer.from(instruction.data, 'base64'),
    };
  }
}
